/**
 * Search field (spec/02 §2.2): the field of SbTextField with the search icon (24 dp, textMuted) at the start and,
 * while the value is not empty, the 48 dp button „Suche leeren“ (close, textMuted; clearSearch from the words table)
 * at the end. The button and Escape in the filled input empty it and keep the focus in it; that Escape is consumed, so
 * it closes no dialog or sheet around the field (Escape on the button passes on, as sb-search.js). With a
 * [placeholder] the label is only the field's name for TalkBack (sb-visually-hidden), else it stands above. The IME action is Search: [onSearch] gets the value, the keyboard closes.
 * [error] (§14.12) = the 2 dp danger baseline and the sentence under it, as SbTextField („Kein Treffer für „Glas“.“
 * in a find bar).
 */
@Composable
fun SbSearchField(
    value: String,
    onValueChange: (String) -> Unit,
    label: String,
    modifier: Modifier = Modifier,
    placeholder: String? = null,
    enabled: Boolean = true,
    onSearch: ((String) -> Unit)? = null,
    error: String? = null,
) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val m = sbMessages()
    val focus = remember { FocusRequester() }
    val interaction = remember { MutableInteractionSource() }
    val inputFocused by interaction.collectIsFocusedAsState()
    var escapeDown by remember { mutableStateOf(false) }
    SbFieldInput(
        value = value,
        onValueChange = onValueChange,
        label = label,
        showLabel = placeholder == null,
        optional = false,
        modifier = modifier
            .focusRequester(focus)
            .onPreviewKeyEvent { e ->
                if (e.key != Key.Escape) return@onPreviewKeyEvent false
                when (e.type) {
                    // only from the input, as sb-search.js: Escape on „Suche leeren“ passes on
                    KeyEventType.KeyDown -> if (value.isEmpty() || !inputFocused) {
                        false
                    } else {
                        onValueChange("")
                        escapeDown = true
                        true
                    }
                    KeyEventType.KeyUp -> escapeDown.also { escapeDown = false }
                    else -> false
                }
            },
        placeholder = placeholder,
        suffix = null,
        help = null,
        counter = null,
        error = error,
        enabled = enabled,
        singleLine = true,
        keyboardOptions = KeyboardOptions(imeAction = ImeAction.Search),
        keyboardActions = KeyboardActions(
            onSearch = {
                onSearch?.invoke(value)
                defaultKeyboardAction(ImeAction.Done)
            },
        ),
        interaction = interaction,
        leading = { Icon(SebaroIcons.Outline.Search, contentDescription = null, tint = c.textMuted, modifier = Modifier.size(t.size.iconLg)) },
        trailing = if (value.isEmpty()) {
            null
        } else {
            {
                SbIconButton(
                    SebaroIcons.Outline.Close,
                    m.clearSearch,
                    onClick = {
                        onValueChange("")
                        focus.requestFocus()
                    },
                    enabled = enabled,
                )
            }
        },
    )
}
